<?php
require_once dirname(__DIR__).'/app/bootstrap.php';
if($_SERVER['REQUEST_METHOD']!=='POST')redirect(app_path('marketplace.php'));verify_csrf();
$action=(string)($_POST['action']??'');$id=(int)($_POST['listing_id']??0);$s=db()->prepare("SELECT id,slug,name,owner_user_id FROM listings WHERE id=:id AND status='published'");$s->execute([':id'=>$id]);$listing=$s->fetch();if(!$listing){flash('error','That business could not be found.');redirect(app_path('index.php'));}if(!(int)($listing['owner_user_id']??0)){flash('error','This business has not enabled owner-managed bookings or quotes yet. Use the general enquiry form instead.');redirect(app_path('index.php?listing='.rawurlencode($listing['slug'])));}
$name=trim((string)($_POST['name']??current_user()['name']??''));$email=trim((string)($_POST['email']??current_user()['email']??''));$phone=trim((string)($_POST['phone']??''));
if($name===''||text_len($name)>80||!filter_var($email,FILTER_VALIDATE_EMAIL)){flash('error','Enter a valid name and email address.');redirect(app_path('index.php?listing='.rawurlencode($listing['slug'])));}
try{
 if($action==='booking'){
  $date=trim((string)($_POST['booking_date']??''));$time=trim((string)($_POST['booking_time']??''));$party=max(1,min(30,(int)($_POST['party_size']??1)));$notes=trim((string)($_POST['notes']??''));$slotId=(int)($_POST['slot_id']??0);
  $dt=DateTimeImmutable::createFromFormat('!Y-m-d',$date);if(!$dt||$dt->format('Y-m-d')!==$date||$date<date('Y-m-d')||!preg_match('/^([01]\d|2[0-3]):[0-5]\d$/',$time)){throw new RuntimeException('Choose a valid future date and time.');}
  $pdo=db();$pdo->beginTransaction();
  if($slotId){$up=$pdo->prepare('UPDATE availability_slots SET booked_count=booked_count+:inc1 WHERE id=:id AND listing_id=:l AND is_active=1 AND slot_date=:d AND slot_time=:t AND booked_count+:inc2<=capacity');$up->execute([':inc1'=>$party,':inc2'=>$party,':id'=>$slotId,':l'=>$id,':d'=>$date,':t'=>$time]);if($up->rowCount()!==1)throw new RuntimeException('That time slot is no longer available. Choose another slot.');}
  $ins=$pdo->prepare("INSERT INTO bookings(listing_id,slot_id,user_id,guest_name,guest_email,guest_phone,booking_date,booking_time,party_size,notes) VALUES(:l,:slot,:u,:n,:e,:p,:d,:t,:party,:notes)");$ins->execute([':l'=>$id,':slot'=>$slotId?:null,':u'=>current_user_id()?:null,':n'=>$name,':e'=>$email,':p'=>text_substr($phone,0,30),':d'=>$date,':t'=>$time,':party'=>$party,':notes'=>text_substr($notes,0,1000)]);$pdo->commit();notify_user((int)$listing['owner_user_id'],'New booking request','A customer requested a booking for '.(string)$listing['name'].'.','owner/marketplace.php');notify_owner_of_inquiry((int)$id,$name,$email,'Booking Request',"Date: {$date} at {$time}\nParty: {$party}\nNotes: {$notes}");flash('success','Your booking request was sent. It is not confirmed until the business accepts it.');
 }elseif($action==='quote'){
  $request=trim((string)($_POST['request_text']??''));$budget=trim((string)($_POST['budget']??''));$needed=trim((string)($_POST['needed_by']??''));if(text_len($request)<20||text_len($request)>3000)throw new RuntimeException('Describe what you need in at least 20 characters.');
  db()->prepare('INSERT INTO quote_requests(listing_id,user_id,sender_name,sender_email,sender_phone,request_text,budget,needed_by) VALUES(:l,:u,:n,:e,:p,:r,:b,:d)')->execute([':l'=>$id,':u'=>current_user_id()?:null,':n'=>$name,':e'=>$email,':p'=>text_substr($phone,0,30),':r'=>$request,':b'=>text_substr($budget,0,100),':d'=>text_substr($needed,0,30)]);notify_user((int)$listing['owner_user_id'],'New quote request','A customer requested a quote for '.(string)$listing['name'].'.','owner/marketplace.php');notify_owner_of_inquiry((int)$id,$name,$email,'Quote Request',"Request: {$request}\nBudget: {$budget}\nNeeded by: {$needed}");flash('success','Your quote request was sent to the business.');
 }else{throw new RuntimeException('Unknown request type.');}
}catch(Throwable $e){if(isset($pdo)&&$pdo instanceof PDO&&$pdo->inTransaction())$pdo->rollBack();flash('error',$e instanceof RuntimeException?$e->getMessage():'We could not save your request. Please try again.');}
redirect(app_path('index.php?listing='.rawurlencode($listing['slug'])));
